(function(){
  function C(n){ try { return Java.loadClass(n); } catch (e) { return Packages.java.lang.Class.forName(n); } }
  function B(v){ return String(v) === 'true'; }
  if (typeof AutoJS === 'undefined') { throw new Error('端点: server 侧 AutoJS 全局缺失（通道未注入）'); }
  var ps = AutoJS.players();
  if (ps === null || ps.length < 1) { throw new Error('端点: 世界内没有玩家'); }
  var p = ps[0];
  AutoJS.command('/kill @e[type=!player,distance=..48]');
  var L = AutoJS.level();
  var x = p.getX(), y = p.getY(), z = p.getZ();
  var out = { cleaned: false };
  var z1 = AutoJS.summon('minecraft:zombie', x + 3.0, y, z);
  z1.setNoAi(true);
  out.z1MaxHealth = Number(z1.getMaxHealth());
  var h0 = z1.getHealth();
  out.playerHitApplied = B(z1.hurt(p.damageSources().playerAttack(p), 1.0));
  out.dmgByPlayer = Number(h0 - z1.getHealth());
  var z2 = AutoJS.summon('minecraft:zombie', x + 5.0, y, z);
  z2.setNoAi(true);
  var h1 = z2.getHealth();
  out.magicHitApplied = B(z2.hurt(L.damageSources().magic(), 2.0));
  out.dmgMagic = Number(h1 - z2.getHealth());
  AutoJS.command('/kill @e[type=!player,distance=..48]');
  out.cleaned = true;
  return out;
})()
